/**
 * Generated bind-mount files for wp-dev Docker stack.
 *
 * These files are generated by wp-dev and bind-mounted into containers. If they don't
 * exist when Docker compose runs, Docker creates them as directories, which breaks
 * subsequent writes. This module ensures they exist as regular files before compose.
 *
 * Single source of truth: all code (up.ts, reconcile.ts, etc.) uses this module to
 * get the list of generated files and their default content.
 */

import { existsSync, rmdirSync, statSync, readdirSync, writeFileSync, lstatSync } from "node:fs";
import { join, dirname, basename } from "node:path";
import { mkdirSync } from "node:fs";
import type { LoadedConfig } from "../config/load.js";
import { generateRemoteIpConf } from "./network-config.js";
import { logInfo } from "./logger.js";

/**
 * Assert that a path is not a symlink. If it is, throw a clear error.
 * This is a shared helper used by both ensureGeneratedFile and ensureRemoteIpConf.
 *
 * Handles all symlink types:
 * - Valid symlink (target exists)
 * - Dangling symlink (target doesn't exist)
 * - Symlink to directory
 *
 * @param filePath - The path to check
 * @param fileDescription - Human-readable description for error messages
 * @throws Error if the path is a symlink of any kind
 */
export function assertNotSymlink(filePath: string, fileDescription: string): void {
  // Use lstatSync to detect symlinks (including dangling ones).
  // existsSync returns false for dangling symlinks, so we can't rely on it.
  let lstat;
  try {
    lstat = lstatSync(filePath);
  } catch (e) {
    // Path doesn't exist at all (not even as a symlink)
    if (e && typeof e === "object" && "code" in e && e.code === "ENOENT") {
      return;
    }
    throw e;
  }

  if (lstat.isSymbolicLink()) {
    const fileName = basename(filePath);
    throw new Error(
      `${filePath} is a symlink. wp-dev manages ${fileName} — remove the symlink and let wp-dev generate the file. ` +
        `(${fileDescription})`,
    );
  }
}

/**
 * Relative path from configDir to each generated bind-mount file.
 * The path segment before the filename is the "local.path" docker directory.
 */
export interface GeneratedBindMountFile {
  /** Path relative to the docker directory (local.path), e.g. "remoteip.conf" */
  relPath: string;
  /** Generate the initial/default content for the file */
  generateDefault: () => string;
  /** Description for log messages */
  description: string;
}

/**
 * List of generated bind-mount files. Single source of truth.
 * Add new generated files here if they get bind-mounted in docker-compose.yml.
 */
export const GENERATED_BIND_MOUNT_FILES: readonly GeneratedBindMountFile[] = [
  {
    relPath: "remoteip.conf",
    generateDefault: () => generateRemoteIpConf(null),
    description: "Apache RemoteIP configuration (restricts X-Forwarded-For trust)",
  },
];

export interface EnsureResult {
  path: string;
  action: "created" | "healed" | "unchanged" | "error";
  message?: string;
}

/**
 * Self-heal: if the path is an empty directory (Docker created it), remove and return true.
 * If it's a non-empty directory, throw. If it's a symlink, throw (not silently ignored).
 * If it doesn't exist or is a file, return false.
 */
function healIfEmptyDirectory(filePath: string, fileDescription: string): boolean {
  if (!existsSync(filePath)) {
    return false;
  }

  // Symlinks are refused with a clear error - not silently ignored
  assertNotSymlink(filePath, fileDescription);

  const stat = statSync(filePath);
  if (!stat.isDirectory()) {
    return false;
  }

  let entries: string[];
  try {
    entries = readdirSync(filePath);
  } catch {
    entries = [];
  }

  if (entries.length > 0) {
    throw new Error(
      `${filePath} is a non-empty directory and cannot be auto-healed. ` +
        `Manually remove it or its contents, then run wp-dev up again.`,
    );
  }

  rmdirSync(filePath);
  logInfo(`compose-prereq: healed ${filePath} (removed empty directory created by Docker)`);
  return true;
}

/**
 * Ensure a single generated bind-mount file exists as a regular file.
 *
 * - If missing: create it with default content
 * - If empty directory (Docker artifact): remove and create file
 * - If non-empty directory: throw error
 * - If symlink: throw error (wp-dev manages this file)
 * - If already a file: leave unchanged
 */
export function ensureGeneratedFile(
  dockerDir: string,
  file: GeneratedBindMountFile,
): EnsureResult {
  const filePath = join(dockerDir, file.relPath);

  // Symlinks are refused with a clear error before any other check
  assertNotSymlink(filePath, file.description);

  const healed = healIfEmptyDirectory(filePath, file.description);
  if (healed) {
    mkdirSync(dirname(filePath), { recursive: true });
    writeFileSync(filePath, file.generateDefault(), "utf8");
    return { path: filePath, action: "healed", message: file.description };
  }

  if (!existsSync(filePath)) {
    mkdirSync(dirname(filePath), { recursive: true });
    writeFileSync(filePath, file.generateDefault(), "utf8");
    logInfo(`compose-prereq: created ${filePath} (${file.description})`);
    return { path: filePath, action: "created", message: file.description };
  }

  const stat = statSync(filePath);
  if (stat.isDirectory()) {
    return {
      path: filePath,
      action: "error",
      message: `${filePath} is a directory (should be a file)`,
    };
  }

  return { path: filePath, action: "unchanged" };
}

/**
 * Ensure all generated bind-mount files exist as regular files before compose runs.
 *
 * This must be called at the very start of the up path, before ANY compose invocation
 * (including compose run/exec in reconcile fallbacks). This prevents Docker from
 * creating bind-mount targets as directories.
 *
 * @param loaded - The loaded config
 * @throws Error if any file is a non-empty directory
 */
export function ensureGeneratedBindMountFiles(loaded: LoadedConfig): EnsureResult[] {
  const dockerDir = join(loaded.configDir, loaded.config.local.path);
  const results: EnsureResult[] = [];

  for (const file of GENERATED_BIND_MOUNT_FILES) {
    const result = ensureGeneratedFile(dockerDir, file);
    results.push(result);
    if (result.action === "error") {
      throw new Error(result.message);
    }
  }

  return results;
}

/**
 * Get the absolute path to a generated bind-mount file.
 * Use this instead of hardcoding paths elsewhere.
 */
export function getGeneratedFilePath(
  loaded: LoadedConfig,
  relPath: string,
): string {
  return join(loaded.configDir, loaded.config.local.path, relPath);
}

/**
 * Get the path to remoteip.conf for a loaded config.
 * Convenience function for the most common generated file.
 */
export function getRemoteIpConfPath(loaded: LoadedConfig): string {
  return getGeneratedFilePath(loaded, "remoteip.conf");
}
